function updateProgress(){let n=0,d=1,text='';if(job.phase==='clean'){n=job.cleaningProgress;d=1;text=`${cleanTool==='brush'?'除尘':'清洗'} ${Math.round(n*100)}% · ${job.cleaned.size}/${job.spec.dirt.length}`;}else if(job.phase==='assemble'){n=job.installed.size;d=job.spec.parts.length;text=`${n} / ${d}`;}else if(job.phase==='screw'){n=job.bolts.reduce((a,b)=>a+b,0);d=job.bolts.length;text=job.boltsPlaced[activeBolt]?`${Math.round(job.bolts[activeBolt]*100)}%`:'待放入';const t=$('turns');if(t)t.textContent=`${(job.bolts[activeBolt]*2).toFixed(1)} / 2 圈`;const w=$('turn-wheel');if(w){w.style.setProperty('--turn',`${job.bolts[activeBolt]*720}deg`);w.style.setProperty('--fill',`${job.bolts[activeBolt]*360}deg`);}}else if(job.phase==='repair'){n=job.activeTask.fraction;d=1;text=job.activeTask.type==='pump'?`胎压 ${Math.round(job.activeTask.level*100)} · 待检查`:`${Math.round(n*100)}% · ${job.repairs.indexOf(job.activeTask)+1}/${job.repairs.length} 步`;}else if(job.phase==='tune'){n=job.tuneStable;d=.6;text=job.tuned?'好声音！':'寻找信号';const e=$('signal');if(e){e.textContent=job.tuned?'就是这里，保持一下…':'把旋钮调到绿色区，保持片刻。';e.classList.toggle('ready',job.tuned);}}else{n=job.testProgress;text=job.completed?'已完成':`${Math.round(n*100)}%`;}$('task-fill').style.width=`${clamp(n/d)*100}%`;$('step-count').textContent=text;$('time').textContent=format(job.time);}
function positionHotspots(){if(job.phase==='repair'){specials.positionHotspots();return;}for(const b of hotspots.children){let node;if(b.dataset.slot)node=machine.slots[b.dataset.slot];else if(b.dataset.bolt!==undefined)node=machine.bolts[+b.dataset.bolt];else node=machine.parts.dial;const p=screen(node);b.style.left=`${p.x}px`;b.style.top=`${p.y}px`;b.classList.toggle('ready',!!b.dataset.slot&&selected===b.dataset.slot);}}
function consume(){let phaseChange=false,renderAgain=false;for(const e of job.events.splice(0)){if(e.type==='wrong'){toast('这个零件不属于这里，换一个接口试试。');audio.play('bump');}if(e.type==='clean'){const p=machine.dirt[e.index].getWorldPosition(new T.Vector3());world.burst(p.x,p.y,p.z,0xffe9b4,3);if(performance.now()-lastSound>80){audio.tone(500+e.index*40,.06,'sine',.015);lastSound=performance.now();}}if(e.type==='placeBolt'){foley.seat();toast('螺丝就位，顺时针转动拧进去。');renderAgain=true;}if(e.type==='install'){const m=machine.parts[e.id];m.scale.setScalar(1);const p=m.getWorldPosition(new T.Vector3());world.burst(p.x,p.y,p.z,0xf5d77d,9);foley.seat();toast('咔哒，接口贴合了。');selected=null;renderAgain=true;}if(e.type==='bolt'){foley.click(1);audio.tone(800,.08,'sine',.025,.08);toast('到位了！螺丝头已经贴平。');resetGesture();activeBolt=Math.max(0,job.bolts.findIndex(v=>v<1));renderAgain=true;}if(e.type==='calibrated'){audio.play('checkpoint');toast('找到了，清清楚楚的好声音。');}if(e.type==='phase'){phaseChange=true;}if(e.type==='repairStep'){foley.seat();toast(e.name+'，完成！');renderAgain=true;}if(e.type==='repairWrong'){toast(e.repairType==='wire'?'颜色不对，再看看线头和插孔。':e.repairType==='pump'?(job.activeTask?.level>.85?'胎压偏高，放一点气再检查。':'胎压偏低，再打几次气后检查。'):e.repairType==='strings'?'音还没准，调一调张力再拨弦。':'跟着金色标记的顺序来就好。');audio.play('bump');}if(e.type==='complete'){updateGallery();if(job.spec.id==='bike'){audio.tone(1350,.18,'sine',.04);audio.tone(1760,.25,'sine',.025,.08);}audio.play('complete');world.burst(0,2,.8,0xffd96b,24);toast(job.spec.finish);save();}}
 if(phaseChange){resetGesture();renderAgain=true;}syncModel();if(renderAgain)render();updateProgress();save();}
function distance(p,a,b){const dx=b.x-a.x,dy=b.y-a.y;const t=clamp(((p.x-a.x)*dx+(p.y-a.y)*dy)/(dx*dx+dy*dy||1));return Math.hypot(p.x-a.x-t*dx,p.y-a.y-t*dy);}
function brushAt(p,amount,tool){const r=canvas.getBoundingClientRect();ray.setFromCamera(new T.Vector2(p.x/r.width*2-1,-p.y/r.height*2+1),world.camera);const hits=ray.intersectObjects(machine.dirt.filter((_,i)=>!job.cleaned.has(i)),false);let touched=false,wetness=0;for(const hit of hits.slice(0,3)){const i=machine.dirt.indexOf(hit.object);if(i<0||!hit.uv)continue;const changed=job.brush(i,hit.uv.x,1-hit.uv.y,tool==='spray'?.5:.33,amount,tool);if(!changed)continue;touched=true;wetness=Math.max(wetness,job.surfaces[i].moisture);toolTarget.copy(hit.point);toolTarget.z+=tool==='spray'?.85:tool==='brush'?.18:.17;if(performance.now()-lastEffects>45){fxDetails.emit(hit.point,tool==='spray'?'foam':'spark',3);lastEffects=performance.now();}const feel=$('clean-feel');if(feel)feel.textContent=tool==='brush'?'刷毛扫过的地方，积灰正在掉落。':tool==='spray'?'泡沫正在浸润污层，换海绵来回擦。':job.surfaces[i].moisture>.3?'湿润的污层正在脱落。':'这块有点干，喷点泡沫更容易擦。';}if(touched){needsPaint=true;if(tool==='spray')foley.spray();else foley.stroke(wetness,amount*20);if(job.events.length)consume();}return touched;}
function wipe(a,b,e){const length=Math.hypot(b.x-a.x,b.y-a.y);if(length<1)return;const count=Math.min(35,Math.max(1,Math.ceil(length/4)));for(let i=1;i<=count&&job.phase==='clean';i++)brushAt({x:a.x+(b.x-a.x)*i/count,y:a.y+(b.y-a.y)*i/count},cleanTool==='spray'?.18:.3,cleanTool);toolTilt=Math.atan2(b.y-a.y,b.x-a.x)*.15;strokeAmount=Math.min(1,length/15);}
function beginInstall(id,slot){if(pendingInstall||job.phase!=='assemble')return;const spec=job.spec.parts.find(p=>p.id===id);if(!spec||spec.slot!==slot){job.install(id,slot);consume();return;}const model=machine.parts[id];pendingInstall={id,slot,t:0,from:new T.Vector3(...spec.position).add(new T.Vector3(.16,.13,.85)),to:new T.Vector3(...spec.position)};model.position.copy(pendingInstall.from);model.visible=true;toast('对准接口，慢慢推入…');}
function placeScrew(i){if(job.placeBolt(i)){boltDrop={index:i,t:0};selected=null;consume();}}
function turnScrew(delta){if(!job.boltsPlaced[activeBolt]||motor<0)return;const before=job.bolts[activeBolt];if(job.tighten(activeBolt,screwAmount(delta))){if(Math.floor(before*8)!==Math.floor(job.bolts[activeBolt]*8))foley.click(job.bolts[activeBolt]);if(delta<0)toast('逆时针会松开，顺着箭头拧紧。');syncModel();updateProgress();if(job.events.length)consume();}}

function start(e,kind,data={}){if(paused||gesture||pendingInstall||e.button>0)return false;audio.unlock();gesture={id:e.pointerId,kind,element:e.currentTarget,last:local(e),...data};try{e.currentTarget.setPointerCapture(e.pointerId);}catch{}e.preventDefault();return true;}
canvas.addEventListener('pointerdown',e=>{if(job.phase==='clean'&&start(e,'wipe')){const p=toWorld(e);if(p)toolTarget.copy(p);const contact=ray.intersectObjects(machine.dirt.filter((_,i)=>!job.cleaned.has(i)),false)[0];if(contact){toolTarget.copy(contact.point);toolTarget.z+=cleanTool==='spray'?.85:.18;}room.sponge.position.copy(toolTarget);room.brush.position.copy(toolTarget);room.spray.position.copy(toolTarget);if(cleanTool==='spray')brushAt(local(e),.4,'spray');else if($('clean-feel'))$('clean-feel').textContent=cleanTool==='brush'?'沿着灰尘轻轻来回扫。':'按住不动不会清洁，轻轻来回擦。';}});
tools.addEventListener('pointerdown',e=>{const part=e.target.closest('[data-part]'),screw=e.target.closest('[data-screw]'),hold=e.target.closest('[data-hold]'),cmp=e.target.closest('[data-compare]'),wheel=e.target.closest('#turn-wheel');if(part&&!part.disabled&&start(e,'part',{part:part.dataset.part,startX:e.clientX,startY:e.clientY,moved:false})){selected=part.dataset.part;document.querySelectorAll('.part-card').forEach(b=>b.classList.toggle('selected',b.dataset.part===selected));part.classList.add('dragging');const ghost=machine.parts[selected].clone(true);ghost.visible=true;ghost.scale.setScalar(1);machine.root.add(ghost);machine.ghost=ghost;const p=toWorld(e);if(p)ghost.position.copy(machine.root.worldToLocal(p.clone()));positionHotspots();}else if(screw&&start(e,'screwPart',{startX:e.clientX,startY:e.clientY,moved:false})){selected='screw';screw.classList.add('selected');const ghost=new T.Group();for(const child of machine.bolts[activeBolt].children)ghost.add(child.clone(true));machine.root.add(ghost);machine.ghost=ghost;const p=toWorld(e);if(p)ghost.position.copy(p);ghost.rotation.z=.3;}else if(wheel){const r=wheel.getBoundingClientRect(),center={x:r.x+r.width/2,y:r.y+r.height/2};start(e,'wheel',{center,angle:Math.atan2(e.clientY-center.y,e.clientX-center.x)});}else if(hold&&start(e,hold.dataset.hold)){hold.classList.add('pressed');}else if(cmp&&start(e,'compare')){compare=true;syncModel();}});
hotspots.addEventListener('pointerdown',e=>{const b=e.target.closest('button');if(!b||paused||pendingInstall)return;if(b.dataset.slot){audio.unlock();if(selected)beginInstall(selected,b.dataset.slot);else toast('先选下方的零件，再点这个接口。');e.preventDefault();}else if(b.dataset.bolt!==undefined){activeBolt=+b.dataset.bolt;showWhole=false;if(!job.boltsPlaced[activeBolt]){if(selected==='screw')placeScrew(activeBolt);else{render();toast('把下方的十字螺丝拖进这个孔。');}return;}const p=screen(machine.bolts[activeBolt]),v=local(e);start(e,'circle',{angle:Math.atan2(v.y-p.y,v.x-p.x),node:machine.bolts[activeBolt]});render();}else if('dial'in b.dataset){const p=screen(machine.parts.dial),v=local(e);start(e,'dial',{angle:Math.atan2(v.y-p.y,v.x-p.x),node:machine.parts.dial});}});
window.addEventListener('pointermove',e=>{if(!gesture||e.pointerId!==gesture.id)return;const p=local(e);if(gesture.kind==='wipe'){wipe(gesture.last,p,e);}if(gesture?.kind==='part'){gesture.moved ||= Math.hypot(e.clientX-gesture.startX,e.clientY-gesture.startY)>8;const v=toWorld(e);if(v&&machine.ghost){const spec=job.spec.parts.find(s=>s.id===gesture.part),target=screen(machine.slots[spec.slot]);machine.ghost.position.copy(machine.root.worldToLocal(v.clone()));if(Math.hypot(target.x-p.x,target.y-p.y)<46){machine.ghost.position.lerp(new T.Vector3(...spec.position).add(new T.Vector3(0,0,.25)),.65);machine.ghost.rotation.z=Math.sin(elapsed*10)*.025;}}positionHotspots();}if(gesture?.kind==='screwPart'){gesture.moved ||= Math.hypot(e.clientX-gesture.startX,e.clientY-gesture.startY)>8;const p=toWorld(e);if(p&&machine.ghost)machine.ghost.position.copy(machine.root.worldToLocal(p.clone()));}if(['circle','dial','wheel'].includes(gesture?.kind)){const g=gesture,c=g.kind==='wheel'?g.center:screen(g.node),v=g.kind==='wheel'?{x:e.clientX,y:e.clientY}:p,a=Math.atan2(v.y-c.y,v.x-c.x),delta=clockwiseDelta(g.angle,a);g.angle=a;if(Math.hypot(v.x-c.x,v.y-c.y)>(g.kind==='wheel'?15:10)){if(g.kind==='dial'){job.tune(job.tuneValue+delta/TAU);const range=tools.querySelector('input');if(range)range.value=job.tuneValue*100;}else turnScrew(delta);}}if(gesture){gesture.last=p;gesture.client={x:e.clientX,y:e.clientY};}},{passive:false});
function end(e){if(!gesture||e.pointerId!==gesture.id)return;const g=gesture,p=local(e);if(g.kind==='part'&&g.moved){let slot=null,best=45;for(const spec of job.spec.parts){if(job.installed.has(spec.id))continue;const c=screen(machine.slots[spec.slot]),d=Math.hypot(c.x-p.x,c.y-p.y);if(d<best){best=d;slot=spec.slot;}}resetGesture();if(slot)beginInstall(g.part,slot);else toast('对准接口再松手，或先点零件再点接口。');}else if(g.kind==='screwPart'&&g.moved){const c=screen(machine.bolts[activeBolt]);resetGesture();if(Math.hypot(c.x-p.x,c.y-p.y)<55)placeScrew(activeBolt);else toast('把螺丝放到发光的孔位上。');}else{resetGesture();syncModel();}save();}
window.addEventListener('pointerup',end);window.addEventListener('pointercancel',()=>{resetGesture();syncModel();});window.addEventListener('blur',()=>{resetGesture();save();});document.addEventListener('visibilitychange',()=>{resetGesture();save();});
tools.addEventListener('input',e=>{if(job.phase==='tune'&&e.target.matches('input[type=range]')){audio.unlock();job.tune(+e.target.value/100);if(performance.now()-lastSound>90){audio.tone(170+job.tuneValue*700,.06,'sine',.018);lastSound=performance.now();}save();}});
tools.addEventListener('click',e=>{const tool=e.target.closest('[data-tool]');if(tool){if(job.spec.cleaning!=='wash'||!['spray','wipe'].includes(tool.dataset.tool))return;cleanTool=tool.dataset.tool;render();return;}if(e.target.closest('[data-ratchet]')){audio.unlock();if(job.phase==='screw'&&job.boltsPlaced[activeBolt])motor=Math.PI/2;return;}if(e.target.closest('[data-view]')){showWhole=!showWhole;render();return;}if(e.target.closest('[data-next]')&&performance.now()-doneAt>450){if(!job.returned){desk.open();return;}nextOrder();}});
function menu(open){if(open&&desk?.opened)desk.close();paused=open;resetGesture();$('menu').classList.toggle('hidden',!open);if(open){menuLists();$('close-menu').focus();}else $('open-menu').focus();}
$('open-menu').onclick=()=>menu(true);$('help').onclick=()=>menu(true);$('close-menu').onclick=()=>menu(false);$('menu').addEventListener('click',e=>{if(e.target===$('menu'))menu(false);});
for(const id of ['side-jobs','menu-jobs'])$(id).addEventListener('click',e=>{const b=e.target.closest('[data-job]');if(!b)return;index=+b.dataset.job;job=jobs[index];menu(false);build();save();});
$('restart').onclick=()=>{jobs[index]=new RepairJob(JOBS[index]);job=jobs[index];menu(false);save();build();toast('工作台收拾好了，从头再来。');};
$('sound').onclick=()=>{audio.toggle();soundUI();if(audio.enabled)audio.play('checkpoint');save();};
if(document.fullscreenEnabled){$('fullscreen').classList.remove('hidden');$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('这个浏览器暂时不能全屏，直接玩也可以。');}};}
window.addEventListener('keydown',e=>{if(e.key==='Escape')menu(!paused);if((e.key===' '||e.key==='Enter')&&!e.repeat&&!paused&&e.target===document.body&&['test'].includes(job.phase)){e.preventDefault();audio.unlock();gesture={kind:job.phase,id:'keyboard'};}});window.addEventListener('keyup',e=>{if((e.key===' '||e.key==='Enter')&&gesture?.id==='keyboard')resetGesture();});
window.addEventListener('resize',resize);window.visualViewport?.addEventListener('resize',resize);window.addEventListener('pagehide',save);
try{world=new World(canvas);fxDetails=new RepairFX(world.scene);world.sun.shadow.bias=-.001;world.sun.shadow.normalBias=.055;Object.assign(world.sun.shadow.camera,{left:-8,right:8,top:8,bottom:-8});world.sun.shadow.camera.updateProjectionMatrix();specials=new SpecialRepairs({get:()=>({job,world,machine,room,paused,audio,foley}),canvas,tools,hotspots,local,toWorld,consume,render,save});desk=new CustomerDesk({get:()=>({job,jobs,cards}),pause:open=>{paused=open;resetGesture();},save,render,next:nextOrder});soundUI();build();$('loading').classList.add('hidden');requestAnimationFrame(frame);}catch(error){$('loading').textContent='3D 工作台暂时没有打开，请刷新或换一个支持 WebGL 的浏览器。';console.error(error);}
function frame(now){const dt=Math.min(.05,(now-lastFrame)/1000);lastFrame=now;if(!paused&&!document.hidden){elapsed+=dt;
 if(pendingInstall){const p=pendingInstall;p.t+=dt;const a=clamp(p.t/.42),ease=1-Math.pow(1-a,3),node=machine.parts[p.id];node.position.lerpVectors(p.from,p.to,ease);node.rotation.z=Math.sin(a*Math.PI)*.08;if(a>=1){pendingInstall=null;node.position.copy(p.to);node.rotation.z=0;job.install(p.id,p.slot);consume();}}
 if(boltDrop){boltDrop.t+=dt;const b=machine.bolts[boltDrop.index];b.position.z=b.userData.baseZ+.28+.45*Math.pow(1-clamp(boltDrop.t/.35),2);if(boltDrop.t>=.35)boltDrop=null;}
 if(motor>0){const delta=Math.min(motor,dt*5);motor-=delta;turnScrew(delta);if(motor<=0)save();}
 if(gesture?.kind==='wipe'&&job.phase==='clean'){if(cleanTool==='spray'){brushAt(gesture.last,dt*4.5,'spray');room.spray.visible=true;room.spray.position.lerp(toolTarget,1-Math.exp(-dt*25));room.spray.rotation.z=Math.sin(elapsed*20)*.025;}else{const contactTool=cleanTool==='brush'?room.brush:room.sponge;contactTool.visible=true;contactTool.position.lerp(toolTarget,1-Math.exp(-dt*35));contactTool.rotation.z+=(toolTilt-contactTool.rotation.z)*.25;if(cleanTool==='brush'){contactTool.rotation.y=Math.sin(elapsed*24)*strokeAmount*.09;contactTool.scale.z=1-strokeAmount*.12;}else contactTool.scale.z=.8-strokeAmount*.2;strokeAmount*=.85;}}
 job.update(dt,gesture?.kind==='test');if(job.events.length)consume();
 const power=compare?0:job.completed?1:job.testProgress;const fx=machine.fx;if(fx.rotor)fx.rotor.rotation.z-=dt*(power*22);if(fx.ribbons){fx.ribbons.visible=power>.05;fx.ribbons.children.forEach((m,i)=>{m.rotation.x=Math.sin(elapsed*14+i)*.3*power;m.rotation.z=(i-1)*.3+power*.5;});}
 if(fx.dial)fx.dial.rotation.z=-job.tuneValue*Math.PI*1.7;if(fx.bars)fx.bars.forEach((m,i)=>m.scale.y=.045+(power>0?(1+Math.sin(elapsed*7+i*1.7))*.07:job.tuned?.09:.025));if(fx.eyes)fx.eyes.forEach(m=>m.material=mat(power>.2?0xffe16b:0x8da098));if(fx.arms)fx.arms.forEach((a,i)=>a.rotation.z=power*(i===0?-.25:Math.sin(elapsed*5)*.5+.8));machine.root.position.y=job.spec.id==='robot'?Math.sin(elapsed*4)*.025*power:0;room.customer.arms[1].rotation.z=power*(Math.sin(elapsed*4)*.25+.7);
 room.driver.visible=job.phase==='screw'&&job.boltsPlaced[activeBolt]&&!compare&&!boltDrop;if(room.driver.visible){room.driver.position.copy(machine.bolts[activeBolt].getWorldPosition(new T.Vector3()));room.driver.position.z+=.045;room.driver.rotation.z=-job.bolts[activeBolt]*Math.PI*4;}
 if(power>.2&&job.spec.id==='clock'&&Math.floor(elapsed*2)!==Math.floor((elapsed-dt)*2))audio.tone(Math.floor(elapsed*2)%2?780:600,.025,'square',.009);animateExtra(machine,job,elapsed,dt,power,compare);specials.update(dt,elapsed);room.waiting.forEach((a,i)=>{a.head.rotation.z=Math.sin(elapsed*1.2+i)*.025;a.arms[1].rotation.z=Math.sin(elapsed*1.7+i)*.05;});if(power>.2&&job.spec.id==='guitar')audio.music(elapsed,'stretch');if(power>.2&&job.spec.id==='radio')audio.music(elapsed,'stretch');if(power>.1&&job.spec.id==='fan'&&Math.floor(elapsed*5)!==Math.floor((elapsed-dt)*5))audio.tone(100+Math.sin(elapsed)*20,.19,'sine',.005);world.update(dt);fxDetails.update(dt);if(needsPaint){syncModel();needsPaint=false;}updateCamera(dt);updateProgress();positionHotspots();}
 world.render();requestAnimationFrame(frame);}
